True def transform(grid):
    n = len(grid[0])
    center = grid[0].index(2)
    out = [[0] * n for _ in range(n)]
    for r in range(n):
        for c in (center - r, center + r):
            if 0 <= c < n:
                out[r][c] = 2
        if r >= 3:
            for c in range(n):
                if (c - r - 2) % 4 == 0 and abs(c - center) <= r - 2:
                    out[r][c] = 1
    return out
